import json, re, os
from pathlib import Path
import xml.etree.ElementTree as ET

JSON_PATH = '/root/training_feedback.json'
EXTRACTED_DIR = Path('/tmp/hwpx_work/template_extracted')

with open(JSON_PATH, 'r', encoding='utf-8') as f:
    data = json.load(f)

def digits_only(v):
    s = '' if v is None else str(v)
    ds = re.findall(r'\d+', s)
    return ''.join(ds)

def format_satisfaction(v):
    s = '' if v is None else str(v)
    m = re.search(r'(\d+(?:\.\d+)?)', s)
    if not m:
        raise ValueError(f'만족도 value has no number: {v!r}')
    score = float(m.group(1))
    return f"{score:.1f}점 (5.0점 만점)"

def format_overall(v):
    base = '' if v is None else str(v)
    base = base.rstrip()
    return base + ' 후속 심화반 검토 요망.'

def replacement_for(key: str) -> str:
    if key not in data:
        raise KeyError(f'Missing key in JSON: {key}')
    if key == '참석자수':
        return digits_only(data[key])
    if key == '만족도':
        return format_satisfaction(data[key])
    if key == '종합의견':
        return format_overall(data[key])
    return '' if data[key] is None else str(data[key])

PLACEHOLDER_RE = re.compile(r'\{\{([^{}]+)\}\}')

CACHE_LOCALNAMES = {
    'linesegarray', 'lineSegArray', 'linesegArray',
    'lineseg', 'lineSeg',
}

def localname(tag: str) -> str:
    return tag.split('}', 1)[1] if tag.startswith('{') else tag

modified_files = []

for xml_path in sorted(EXTRACTED_DIR.rglob('*.xml')):
    raw = xml_path.read_text('utf-8')
    try:
        root = ET.fromstring(raw)
    except ET.ParseError as e:
        raise RuntimeError(f'Failed to parse {xml_path}: {e}')

    # Build parent map for removals
    parent = {c: p for p in root.iter() for c in p}

    any_changes = False

    # Modify per paragraph so we can drop cache elements only when needed
    for p in [e for e in root.iter() if localname(e.tag) == 'p']:
        t_elems = [e for e in p.iter() if localname(e.tag) == 't']
        if not t_elems:
            continue
        full_text = ''.join([(e.text or '') for e in t_elems])
        if '{{' not in full_text:
            continue

        # Replace placeholders in the concatenated paragraph text
        def _sub(m):
            k = m.group(1)
            return replacement_for(k)

        new_full = PLACEHOLDER_RE.sub(_sub, full_text)
        if new_full != full_text:
            any_changes = True

        # Put the entire paragraph text into the first <...:t>
        t_elems[0].text = new_full
        for extra in t_elems[1:]:
            extra.text = ''

        # Remove layout/cache elements associated with this paragraph
        # Remove any descendant whose localname matches cache tags
        to_remove = []
        for d in p.iter():
            if d is p:
                continue
            if localname(d.tag) in CACHE_LOCALNAMES:
                to_remove.append(d)
        # Remove deepest nodes first
        for node in reversed(to_remove):
            par = parent.get(node)
            if par is not None:
                par.remove(node)
                any_changes = True

    if any_changes:
        # Preserve original declaration/encoding
        out = ET.tostring(root, encoding='utf-8', xml_declaration=True)
        xml_path.write_bytes(out)
        modified_files.append(str(xml_path))

print('Modified XML files:', len(modified_files))
for p in modified_files:
    print(' -', p)

# Sanity: ensure no placeholders remain
remaining = []
for xml_path in sorted(EXTRACTED_DIR.rglob('*.xml')):
    txt = xml_path.read_text('utf-8')
    if '{{' in txt:
        remaining.append(str(xml_path))
if remaining:
    raise SystemExit('Placeholders still remain in: ' + ', '.join(remaining))

print('No placeholders remain in extracted XML.')
